import{_ as p,a0 as s,w as a,s as u,I as n,x as o,a1 as r,A as l,ao as e}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const v=JSON.parse('{"title":"Arch Linux 安装捷径：Evo/Lution | LCTT x X-CMD","titleTemplate":false,"description":"Arch Linux 安装捷径：Evo/Lution | LCTT (201411) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Arch Linux 安装捷径：Evo/Lution | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Arch Linux 安装捷径：Evo/Lution | LCTT (201411) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201411/20140919 How to install Arch Linux the easy way with Evo or Lution","title":"Arch Linux 安装捷径：Evo/Lution","tag":"201411","desc":""},"relativePath":"201411/20140919 How to install Arch Linux the easy way with Evo or Lution.md","filePath":"[post].md"}'),m={name:"201411/20140919 How to install Arch Linux the easy way with Evo or Lution.md"};function f(d,t,L,x,g,w){const i=s("Link");return a(),u("div",null,[t[24]||(t[24]=n("h1",{id:"arch-linux-安装捷径-evo-lution",tabindex:"-1"},[o("Arch Linux 安装捷径：Evo/Lution "),n("a",{class:"header-anchor",href:"#arch-linux-安装捷径-evo-lution","aria-label":"Permalink to “Arch Linux 安装捷径：Evo/Lution”"},"​")],-1)),t[25]||(t[25]=n("p",null,"有些人只体验过Ubuntu或Mint的安装，却鼓起勇气想要安装Arch Linux，他们的学习道路是那样的陡峭和严峻，安装过程中半途而废的人数可能要比顺利过关的人多得多。如果你成功搭建并按你所需的配置好了Arch Linux，那么它已经把你培养成了一个饱经风霜的Linux用户。",-1)),n("p",null,[t[1]||(t[1]=o("即使有",-1)),r(i,{href:"https://wiki.archlinux.org/"},{default:l(()=>[...t[0]||(t[0]=[o("可以帮助你的维基",-1)])]),_:1}),t[2]||(t[2]=o("为新手提供指南，对于那些想要征服Arch的人而言要求仍然太高。你需要至少熟悉诸如fdisk或mkfs之类的终端命令，并且听过mc、nano或chroot这些，并努力掌握它们。这让我回想起了10年前的Debian安装。",-1))]),n("p",null,[t[4]||(t[4]=o("对于那些满怀抱负而又缺乏知识的生灵，有一个叫",-1)),r(i,{href:"http://www.evolutionlinux.com/"},{default:l(()=>[...t[3]||(t[3]=[o("Evo/Lution Live ISO",-1)])]),_:1}),t[5]||(t[5]=o("的ISO镜像格式安装器可以拯救他们。即便它貌似像发行版一样启动，但它其实除了辅助安装Arch Linux准系统之外啥都不干。Evo/Lution是一个项目，它旨在通过提供Arch的简单安装方式来为Arch的增加更多的用户基数，就像为那些用户提供全面帮助和文档的社区一样。在这样一个组合中，Evo是Live CD（不可安装），而Lution是个安装器本身。项目创立者看到了Arch及其衍生发行版的开发者和用户之间的巨大鸿沟，而想要在所有参与者之间构筑一个身份平等的社区。",-1))]),t[26]||(t[26]=e('<p><img src="https://farm6.staticflickr.com/5559/15067088008_ecb221408c_z.jpg" alt=""></p><p>项目的软件部分是命令行安装器Lution-AIS，它负责解释一个普通的纯净的Arch安装过程中的每一步。安装完毕后，你将获得Arch提供的没有从AUR添加任何东西的最新软件或其它任何自定义的包。</p><p>启动这个422MB大小的ISO镜像后，一个由显示在右边的带有选项快捷方式的Conky和一个左边等待运行安装器的LX-Terminal组成的工作区便呈现在我们眼前。</p><p><img src="https://farm6.staticflickr.com/5560/15067056888_6345c259db_z.jpg" alt=""></p><p>在通过右击桌面或使用ALT-i启动实际的安装器后，一个写满了16个等待运行的任务列表就出现在你面前了。除非你知道你在做什么，否则请将这些任务全部运行一遍。你可以一次运行，也可以进行选择，如1 3 6，或者1-4，也可以一次将它们全部运行，输入1-16。大多数步骤需要‘y’，即‘yes’，来确认，敲击回车即可。在此期间，你有足够的时间来阅读安装指南，它可以通过ALT-g来打开。当然，你也可以出去溜达一圈再回来。</p><p><img src="https://farm4.staticflickr.com/3868/15253227082_5e7219f72d_z.jpg" alt=""></p><p>这16个步骤分成“基础安装”和“桌面安装”两组。第一个组安装主要关注本地化、分区，以及安装启动器。</p><p>安装器带领你穿越分区世界，你可以选择使用gparted、gdisk，以及cfdisk。</p><p><img src="https://farm4.staticflickr.com/3873/15230603226_56bba60d28_z.jpg" alt=""></p><p><img src="https://farm4.staticflickr.com/3860/15253610055_e6a2a7a1cb_z.jpg" alt=""></p><p>创建完分区后（如，像截图中所示，用gparted划分/dev/sda1用于root，/dev/sda2用于swap），你可以在10个文件系统中选择其中之一。在下一步中，你可以选择内核（最新或长期支持LTS）和基础系统。</p><p><img src="https://farm6.staticflickr.com/5560/15253610085_aa5a9557fb_z.jpg" alt=""></p><p>安装完你喜爱的启动加载器后，第一部分安装就完成了，这大约需要花费12分钟。这是在普通的Arch Linux中你第一次重启进入系统所处之处。</p><p>在Lution的帮助下，继续进入第二部分，在这一部分中将安装Xorg、声音和图形驱动，然后进入桌面环境。</p><p><img src="https://farm4.staticflickr.com/3918/15066917430_c21e0f0a9e_z.jpg" alt=""></p><p>安装器会检测是否在VirtualBox中安装，并且会自动为VM安装并加载正确的通用驱动，然后相应地设置<strong>systemd</strong>。</p><p>在下一步中，你可以选择KDE、Gnome、Cinnamon、LXDE、Englightenment、Mate或XFCE作为你的桌面环境。如果你不喜欢臃肿的桌面，你也可以试试这些窗口管理器：Awesome、Fluxbox、i3、IceWM、Openbox或PekWM。</p><p><img src="https://farm4.staticflickr.com/3874/15253610125_26f913be20_z.jpg" alt=""></p><p>在使用Cinnamon作为桌面环境的情况下，第二部分安装将花费不到10分钟的时间；而选择KDE的话，因为要下载的东西多得多，所以花费的时间也会更长。</p><p>Lution-AIS在Cinnamon和Awesome上像个妩媚的小妖精。在安装完成并提示重启后，它就带我进入了我所渴望的环境。</p><p><img src="https://farm4.staticflickr.com/3885/15270946371_c2def59f37_z.jpg" alt=""></p><p>我要提出两点批评：一是在安装器要我选择一个镜像列表时，以及在创建fstab文件时。在这两种情况下，它都另外开了一个终端，给出了一些文本信息提示。这让我花了点时间才搞清楚，原来我得把它关了，安装器才会继续。在创建fstab后，它又会提示你，而你需要关闭终端，并在问你是否想要保存文件时回答‘是’。</p><p><img src="https://farm4.staticflickr.com/3874/15067056958_3bba63da60_z.jpg" alt=""></p><p>我碰到的第二个问题，可能与VirtualBox有关了。在启动的时候，你可以看到没有网络被检测到的提示信息。点击顶部左边的图标，将会打开我们所使用的网络管理器wicd。点击“断开”，然后再点击“连接”并重启安装器，就可以让它自动检测到了。</p>',24)),n("p",null,[t[8]||(t[8]=o("Evo/Lution看起来是个有价值的项目，在这里Lution工作一切顺利，目前还没有什么可告诉社区的。他们开启了一个全新的网站、论坛和维基，需要填充内容进去啊。所以，如果你喜欢这主意，加入",-1)),r(i,{href:"http://www.evolutionlinux.com/forums/"},{default:l(()=>[...t[6]||(t[6]=[o("他们的论坛",-1)])]),_:1}),t[9]||(t[9]=o("并告诉他们吧。本文中的ISO镜像可以从",-1)),r(i,{href:"http://www.evolutionlinux.com/downloads.html"},{default:l(()=>[...t[7]||(t[7]=[o("此网站",-1)])]),_:1}),t[10]||(t[10]=o("下载。",-1))]),t[27]||(t[27]=n("hr",null,null,-1)),n("p",null,[t[12]||(t[12]=o("via: ",-1)),r(i,{href:"http://xmodulo.com/2014/09/install-arch-linux-easy-way-evolution.html"},{default:l(()=>[...t[11]||(t[11]=[o("http://xmodulo.com/2014/09/install-arch-linux-easy-way-evolution.html",-1)])]),_:1})]),n("p",null,[t[16]||(t[16]=o("作者：",-1)),r(i,{href:"http://xmodulo.com/author/ferdinand"},{default:l(()=>[...t[13]||(t[13]=[o("Ferdinand Thommes",-1)])]),_:1}),t[17]||(t[17]=o(" 译者：",-1)),r(i,{href:"https://github.com/GOLinux"},{default:l(()=>[...t[14]||(t[14]=[o("GOLinux",-1)])]),_:1}),t[18]||(t[18]=o(" 校对：",-1)),r(i,{href:"https://github.com/wxy"},{default:l(()=>[...t[15]||(t[15]=[o("wxy",-1)])]),_:1})]),n("p",null,[t[21]||(t[21]=o("本文由 ",-1)),r(i,{href:"https://github.com/LCTT/TranslateProject"},{default:l(()=>[...t[19]||(t[19]=[o("LCTT",-1)])]),_:1}),t[22]||(t[22]=o(" 原创翻译，",-1)),r(i,{href:"http://linux.cn/"},{default:l(()=>[...t[20]||(t[20]=[o("Linux中国",-1)])]),_:1}),t[23]||(t[23]=o(" 荣誉推出",-1))])])}const T=p(m,[["render",f]]);export{v as __pageData,T as default};
